using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;
class GameToolsTests {
 static void A(bool v,string message){if(!v)throw new Exception(message);}
 static void Reject(Action action){bool refused=false;try{action();}catch{refused=true;}A(refused,"Expected refusal");}
 static void Put(string root,string relative,string text){string path=Core.Inside(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text);}
 static void Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"fixer-game-tools-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 string game=Path.Combine(root,"Game"),other=Path.Combine(root,"GameOther");Directory.CreateDirectory(game);Directory.CreateDirectory(other);A(GameTools.Within(game,Path.Combine(game,"bin/Game.exe")),"nested game process");A(!GameTools.Within(game,Path.Combine(other,"Game.exe")),"sibling prefix refused");A(!GameTools.Within(game,Path.Combine(game,"../GameOther/Game.exe")),"traversal outside game refused");
 var planned=new GameProcess{Id=42,Created=100,Path=Path.Combine(game,"Game.exe")};A(GameTools.SameProcess(game,planned,new GameProcess{Id=42,Created=100,Path=planned.Path}),"same process accepted");A(!GameTools.SameProcess(game,planned,new GameProcess{Id=42,Created=101,Path=planned.Path}),"reused PID rejected");A(!GameTools.SameProcess(game,planned,new GameProcess{Id=42,Created=100,Path=Path.Combine(other,"Game.exe")}),"changed executable rejected");A(GameTools.UninstallArgument("4000")=="steam://uninstall/4000","Steam uninstall route");Reject(()=>GameTools.UninstallArgument("4000 -extra"));Reject(()=>GameTools.UninstallArgument("0"));
 Put(game,"steam_api64.dll","original");string hash=Core.Hash(Core.Inside(game,"steam_api64.dll"));string folder="LegacySteamFixer-Auto/archive-"+Guid.NewGuid().ToString("N");var state=new AutoState{Version="0.3.0-test1",Root=game,Files=new List<AutoFile>{new AutoFile{Path="steam_api64.dll",Backup="bin/steam_api64_original.dll",OriginalHash=hash}}};Put(game,folder+"/state.json",new JavaScriptSerializer().Serialize(state));Put(game,folder+"/bin/steam_api64_original.dll","original");Put(game,"save.dat","user save");Put(game,"mods/mod.txt","user mod");GameTools.CleanArchives(game,s=>{});A(!Directory.Exists(Core.Inside(game,folder)),"verified archive removed");A(File.ReadAllText(Core.Inside(game,"steam_api64.dll"))=="original","restored original retained");A(File.Exists(Core.Inside(game,"save.dat"))&&File.Exists(Core.Inside(game,"mods/mod.txt")),"save and mod retained");
 string keep="LegacySteamFixer-Auto/archive-"+Guid.NewGuid().ToString("N");Put(game,keep+"/state.json",new JavaScriptSerializer().Serialize(state));Put(game,keep+"/bin/steam_api64_original.dll","original");Put(game,keep+"/user.txt","extra file");GameTools.CleanArchives(game,s=>{});A(File.Exists(Core.Inside(game,keep+"/bin/steam_api64_original.dll"))&&File.Exists(Core.Inside(game,keep+"/user.txt")),"unknown archive content retained");File.Delete(Core.Inside(game,keep+"/user.txt"));Put(game,keep+"/bin/steam_api64_original.dll","changed backup");GameTools.CleanArchives(game,s=>{});A(File.Exists(Core.Inside(game,keep+"/state.json")),"changed backup retained");
 if(Environment.OSVersion.Platform==PlatformID.Win32NT&&args.Length>0){string fixture=Path.GetFullPath(args[0]),processRoot=Path.GetDirectoryName(fixture);using(var child=Process.Start(new ProcessStartInfo(fixture){UseShellExecute=false,CreateNoWindow=true})){try{List<GameProcess> found=null;for(int retry=0;retry<30;retry++){found=GameTools.Processes(processRoot);if(found.Exists(x=>x.Id==child.Id))break;Thread.Sleep(100);}A(found!=null&&found.Exists(x=>x.Id==child.Id),"x86 controller finds x64 fixture process");GameTools.ForceClose(processRoot,found,s=>{});A(child.WaitForExit(5000),"fixture process terminated");Console.WriteLine("PASS: Windows x86 controller identified and closed its x64 test fixture process.");}finally{if(!child.HasExited){child.Kill();child.WaitForExit();}}}}
 Console.WriteLine("PASS: exact game-directory process boundary, reused PID and changed executable refusal, numeric uninstall routing, verified backup cleanup, retained originals/saves/mods, unknown and changed archive retention. No real process termination or Steam uninstall.");
 }finally{Directory.Delete(root,true);}}
}
